/**
 * @import {FileMetaData} from '../src/types.js'
 */

/**
 * Summarize each column across all row groups.
 * Columns are merged by dotted path, in order of first appearance.
 * The null count is null unless every chunk of the column records one.
 *
 * @param {FileMetaData} metadata
 * @returns {{ name: string, type: string, numValues: number, nullCount: number | null, compressedBytes: number, uncompressedBytes: number }[]}
 */
export function parquetColumnSummary(metadata) {
  /** @type {Map<string, { name: string, type: string, numValues: number, nullCount: number | null, compressedBytes: number, uncompressedBytes: number }>} */
  const columns = new Map()
  for (const { columns: chunks } of metadata.row_groups) {
    for (const { meta_data } of chunks) {
      if (!meta_data) continue
      const name = meta_data.path_in_schema.join('.')
      let summary = columns.get(name)
      if (!summary) {
        summary = {
          name,
          type: meta_data.type,
          numValues: 0,
          nullCount: 0,
          compressedBytes: 0,
          uncompressedBytes: 0,
        }
        columns.set(name, summary)
      }
      summary.numValues += Number(meta_data.num_values)
      summary.compressedBytes += Number(meta_data.total_compressed_size)
      summary.uncompressedBytes += Number(meta_data.total_uncompressed_size)
      const nulls = meta_data.statistics?.null_count
      if (nulls === undefined) summary.nullCount = null
      else if (summary.nullCount !== null) summary.nullCount += Number(nulls)
    }
  }
  return [...columns.values()]
}
